from manim import *
import networkx as nx

class DijkstraScene(Scene):
    def construct(self):
        G = nx.Graph()
        G.add_edges_from([(0,1), (1,2), (0,3), (3,2)])
        pos = {0: [-2,0,0], 1: [0,1.5,0], 3: [0,-1.5,0], 2: [2,0,0]}
        mg = Graph(list(G.nodes), list(G.edges), layout=pos, vertex_config={'radius': 0.2})
